@dataclass(frozen=True)
class AuthSettings:
    """Settings for trusted-header or local mock identity handling."""

    auth_mode: str = "mock"
    provider: str = "oidc"
    claims_header_name: str = "x-authenticated-claims"
    group_delimiter: str = ","
    mock_subject_header: str = "x-mock-subject"
    mock_email_header: str = "x-mock-email"
    mock_display_name_header: str = "x-mock-display-name"
    mock_groups_header: str = "x-mock-groups"
    database_url: str = "sqlite+pysqlite:///./runs/kit/REQ-002/.state/auth.db"
    claim_mapping: IdentityClaimMapping = field(default_factory=IdentityClaimMapping)
    group_role_map: dict[str, tuple[str, ...]] = field(
        default_factory=lambda: dict(DEFAULT_GROUP_ROLE_MAP)
    )
    role_permissions: dict[str, tuple[str, ...]] = field(
        default_factory=lambda: dict(DEFAULT_ROLE_PERMISSIONS)
    )
    role_priority: tuple[str, ...] = DEFAULT_ROLE_PRIORITY

    @classmethod
    def from_env(cls) -> "AuthSettings":
        raw_claim_mapping = _load_json_env("AUTH_CLAIM_MAPPING")
        claim_mapping = (
            IdentityClaimMapping(**raw_claim_mapping)
            if isinstance(raw_claim_mapping, dict)
            else IdentityClaimMapping()
        )

        group_role_map = _coerce_mapping_tuple(
            _load_json_env("AUTH_GROUP_ROLE_MAP") or DEFAULT_GROUP_ROLE_MAP
        )
        role_permissions = _coerce_mapping_tuple(
            _load_json_env("AUTH_ROLE_PERMISSIONS") or DEFAULT_ROLE_PERMISSIONS
        )
        role_priority = _coerce_tuple(
            _load_json_env("AUTH_ROLE_PRIORITY") or list(DEFAULT_ROLE_PRIORITY),
            name="AUTH_ROLE_PRIORITY",
        )

        return cls(
            auth_mode=os.getenv("AUTH_MODE", "mock"),
            provider=os.getenv("AUTH_PROVIDER", "oidc"),
            claims_header_name=os.getenv("AUTH_CLAIMS_HEADER", "x-authenticated-claims"),
            group_delimiter=os.getenv("AUTH_GROUP_DELIMITER", ","),
            mock_subject_header=os.getenv("AUTH_MOCK_SUBJECT_HEADER", "x-mock-subject"),
            mock_email_header=os.getenv("AUTH_MOCK_EMAIL_HEADER", "x-mock-email"),
            mock_display_name_header=os.getenv(
                "AUTH_MOCK_DISPLAY_NAME_HEADER", "x-mock-display-name"
            ),
            mock_groups_header=os.getenv("AUTH_MOCK_GROUPS_HEADER", "x-mock-groups"),
            database_url=os.getenv(
                "DATABASE_URL", "sqlite+pysqlite:///./runs/kit/REQ-002/.state/auth.db"
            ),
            claim_mapping=claim_mapping,
            group_role_map=group_role_map,
            role_permissions=role_permissions,
            role_priority=role_priority,
        )


def _load_json_env(name: str) -> Any | None:
    raw_value = os.getenv(name)
    if raw_value is None or raw_value.strip() == "":
        return None
    return json.loads(raw_value)


def _coerce_mapping_tuple(raw_mapping: Any) -> dict[str, tuple[str, ...]]:
    if not isinstance(raw_mapping, dict):
        raise ValueError("Expected a JSON object for mapping configuration.")

    coerced: dict[str, tuple[str, ...]] = {}
    for key, value in raw_mapping.items():
        if not isinstance(key, str) or key.strip() == "":
            raise ValueError("Mapping keys must be non-empty strings.")

        if isinstance(value, str):
            coerced[key] = (value,)
            continue

        if isinstance(value, list) and all(isinstance(item, str) for item in value):
            coerced[key] = tuple(value)
            continue

        if isinstance(value, tuple) and all(isinstance(item, str) for item in value):
            coerced[key] = value
            continue

        raise ValueError(f"Mapping value for {key!r} must be a string or list of strings.")
    return coerced


def _coerce_tuple(raw_value: Any, *, name: str) -> tuple[str, ...]:
    if isinstance(raw_value, str):
        return (raw_value,)
    if isinstance(raw_value, list) and all(isinstance(item, str) for item in raw_value):
        return tuple(raw_value)
    if isinstance(raw_value, tuple) and all(isinstance(item, str) for item in raw_value):
        return raw_value
    raise ValueError(f"{name} must be a string or list of strings.")
