"""Header-based claim extraction for trusted proxy mode and local mock mode."""

from __future__ import annotations

import json

from fastapi import Request

from backend.app.shared.auth.errors import InvalidIdentityError, MissingIdentityError
from backend.app.shared.auth.models import RawIdentityClaims
from backend.app.shared.config.auth_config import AuthSettings


class HeaderClaimsExtractor:
    """Extracts raw identity claims from trusted headers."""

    def __init__(self, settings: AuthSettings) -> None:
        self._settings = settings

    def has_identity_material(self, request: Request) -> bool:
        if self._settings.auth_mode == "mock":
            headers = request.headers
            return any(
                header_name in headers
                for header_name in (
                    self._settings.mock_subject_header,
                    self._settings.mock_email_header,
                    self._settings.mock_display_name_header,
                    self._settings.mock_groups_header,
                )
            )
        return self._settings.claims_header_name in request.headers

    def extract(self, request: Request) -> RawIdentityClaims:
        if self._settings.auth_mode == "mock":
            return self._extract_mock_headers(request)
        return self._extract_trusted_claims_header(request)

    def _extract_mock_headers(self, request: Request) -> RawIdentityClaims:
        headers = request.headers
        if not self.has_identity_material(request):
            raise MissingIdentityError("Authentication is required for this route.")

        claim_mapping = self._settings.claim_mapping
        raw_claims: dict[str, object] = {}

        subject = headers.get(self._settings.mock_subject_header)
        email = headers.get(self._settings.mock_email_header)
        display_name = headers.get(self._settings.mock_display_name_header)
        groups = headers.get(self._settings.mock_groups_header)

        if subject is not None:
            raw_claims[claim_mapping.subject_claim] = subject
        if email is not None:
            raw_claims[claim_mapping.email_claim] = email
        if display_name is not None:
            raw_claims[claim_mapping.display_name_claim] = display_name
        if groups is not None:
            raw_claims[claim_mapping.groups_claim] = groups

        return raw_claims

    def _extract_trusted_claims_header(self, request: Request) -> RawIdentityClaims:
        raw_header = request.headers.get(self._settings.claims_header_name)
        if raw_header is None or raw_header.strip() == "":
            raise MissingIdentityError("Authentication is required for this route.")

        try:
            claims = json.loads(raw_header)
        except json.JSONDecodeError as exc:
            raise InvalidIdentityError("Identity claims are invalid.") from exc

        if not isinstance(claims, dict):
            raise InvalidIdentityError("Identity claims are invalid.")

        return claims
