"""Claim normalization into a stable application identity."""

from __future__ import annotations

from backend.app.shared.auth.errors import InvalidIdentityError
from backend.app.shared.auth.models import AuthenticatedIdentity, RawIdentityClaims
from backend.app.shared.config.auth_config import IdentityClaimMapping
from backend.app.shared.rbac.service import RolePermissionResolver


class IdentityNormalizer:
    """Maps protocol-specific claims to the app identity contract."""

    def __init__(
        self,
        claim_mapping: IdentityClaimMapping,
        role_permission_resolver: RolePermissionResolver,
        group_delimiter: str = ",",
    ) -> None:
        self._claim_mapping = claim_mapping
        self._role_permission_resolver = role_permission_resolver
        self._group_delimiter = group_delimiter

    def normalize(self, raw_claims: RawIdentityClaims) -> AuthenticatedIdentity:
        subject = self._read_required(raw_claims, self._claim_mapping.subject_claim, "subject")
        email = self._read_required(raw_claims, self._claim_mapping.email_claim, "email")
        display_name = self._read_optional(raw_claims, self._claim_mapping.display_name_claim) or email
        groups = self._read_groups(raw_claims, self._claim_mapping.groups_claim)

        roles = self._role_permission_resolver.resolve_roles(groups)
        permissions = self._role_permission_resolver.resolve_permissions_for_roles(roles)

        return AuthenticatedIdentity(
            subject=subject,
            email=email,
            display_name=display_name,
            groups=groups,
            roles=roles,
            permissions=permissions,
        )

    def _read_required(self, raw_claims: RawIdentityClaims, key: str, label: str) -> str:
        value = self._read_optional(raw_claims, key)
        if value is None or value == "":
            raise InvalidIdentityError(f"Identity claims are invalid: missing {label}.")
        return value

    def _read_optional(self, raw_claims: RawIdentityClaims, key: str) -> str | None:
        value = raw_claims.get(key)
        if value is None:
            return None
        if not isinstance(value, str):
            raise InvalidIdentityError("Identity claims are invalid.")
        trimmed = value.strip()
        return trimmed or None

    def _read_groups(self, raw_claims: RawIdentityClaims, key: str) -> tuple[str, ...]:
        raw_value = raw_claims.get(key)
        if raw_value is None:
            return ()

        candidates: list[str]
        if isinstance(raw_value, str):
            candidates = [item.strip() for item in raw_value.split(self._group_delimiter)]
        elif isinstance(raw_value, list) and all(isinstance(item, str) for item in raw_value):
            candidates = [item.strip() for item in raw_value]
        elif isinstance(raw_value, tuple) and all(isinstance(item, str) for item in raw_value):
            candidates = [item.strip() for item in raw_value]
        else:
            raise InvalidIdentityError("Identity claims are invalid.")

        normalized: list[str] = []
        for item in candidates:
            if item and item not in normalized:
                normalized.append(item)
        return tuple(normalized)
