"""User persistence port and SQLAlchemy implementation."""

from __future__ import annotations

from dataclasses import dataclass
from datetime import datetime
from typing import Any, Callable, Protocol
from uuid import uuid4

from sqlalchemy import Boolean, Column, DateTime, MetaData, String, Table, Uuid, insert, select, update
from sqlalchemy.engine import Engine
from sqlalchemy.orm import Session, sessionmaker

from backend.app.shared.auth.models import AuthenticatedIdentity, PersistedUser

identity_metadata = MetaData()

users_table = Table(
    "users",
    identity_metadata,
    Column("id", Uuid(as_uuid=False), primary_key=True, nullable=False),
    Column("external_subject", String, nullable=False, unique=True),
    Column("email", String, nullable=False, unique=True),
    Column("display_name", String, nullable=False),
    Column("role", String, nullable=False),
    Column("is_active", Boolean, nullable=False, default=True),
    Column("last_login_at", DateTime(timezone=True), nullable=True),
)


class UserIdentityRepository(Protocol):
    """Persistence abstraction for authenticated users."""

    def upsert_authenticated_user(
        self, identity: AuthenticatedIdentity, occurred_at: datetime
    ) -> PersistedUser:
        """Insert or update the authenticated user."""


SessionFactory = Callable[[], Session]


def build_session_factory(engine: Engine) -> SessionFactory:
    """Build a non-expiring SQLAlchemy session factory."""
    return sessionmaker(bind=engine, expire_on_commit=False, class_=Session)


@dataclass(frozen=True)
class SQLAlchemyUserIdentityRepository:
    """SQLAlchemy implementation backed by the shared `users` table."""

    session_factory: SessionFactory

    def upsert_authenticated_user(
        self, identity: AuthenticatedIdentity, occurred_at: datetime
    ) -> PersistedUser:
        with self.session_factory() as session:
            existing = session.execute(
                select(users_table).where(users_table.c.external_subject == identity.subject)
            ).mappings().one_or_none()

            role = identity.primary_role
            if existing is None:
                user_id = str(uuid4())
                session.execute(
                    insert(users_table).values(
                        id=user_id,
                        external_subject=identity.subject,
                        email=identity.email,
                        display_name=identity.display_name,
                        role=role,
                        is_active=True,
                        last_login_at=occurred_at,
                    )
                )
            else:
                user_id = str(existing["id"])
                session.execute(
                    update(users_table)
                    .where(users_table.c.id == existing["id"])
                    .values(
                        email=identity.email,
                        display_name=identity.display_name,
                        role=role,
                        is_active=True,
                        last_login_at=occurred_at,
                    )
                )

            session.commit()

            refreshed = session.execute(
                select(users_table).where(users_table.c.id == user_id)
            ).mappings().one()
            return _row_to_user(refreshed)

    def get_by_subject(self, subject: str) -> PersistedUser | None:
        """Convenience lookup used by tests and diagnostics."""
        with self.session_factory() as session:
            row = session.execute(
                select(users_table).where(users_table.c.external_subject == subject)
            ).mappings().one_or_none()
            return _row_to_user(row) if row is not None else None


def _row_to_user(row: Any) -> PersistedUser:
    return PersistedUser(
        id=str(row["id"]),
        external_subject=str(row["external_subject"]),
        email=str(row["email"]),
        display_name=str(row["display_name"]),
        role=str(row["role"]),
        is_active=bool(row["is_active"]),
        last_login_at=row["last_login_at"],
    )
