"""FastAPI dependencies for protected routes and permission gates."""

from __future__ import annotations

from collections.abc import Callable

from fastapi import Depends, Request

from backend.app.identity.auth.service import IdentityAccessService
from backend.app.shared.auth.errors import AuthorizationError
from backend.app.shared.auth.models import AuthenticatedSession


def get_identity_access_service(request: Request) -> IdentityAccessService:
    return request.app.state.identity_access_service  # type: ignore[no-any-return]


def require_authenticated_session(request: Request) -> AuthenticatedSession:
    authentication_error = getattr(request.state, "authentication_error", None)
    if authentication_error is not None:
        raise authentication_error

    cached_session = getattr(request.state, "authenticated_session", None)
    if cached_session is not None:
        return cached_session

    service = get_identity_access_service(request)
    authenticated_session = service.authenticate_request(request)
    request.state.authenticated_session = authenticated_session
    return authenticated_session


def require_permission(permission: str) -> Callable[..., AuthenticatedSession]:
    def dependency(
        authenticated_session: AuthenticatedSession = Depends(require_authenticated_session),
    ) -> AuthenticatedSession:
        if not authenticated_session.identity.has_permission(permission):
            raise AuthorizationError(f"Missing permission: {permission}")
        return authenticated_session

    return dependency
