"""FastAPI app factory for REQ-002 auth and RBAC behavior."""

from __future__ import annotations

from datetime import datetime
from pathlib import Path
from typing import Callable

from fastapi import Depends, FastAPI, Request
from fastapi.responses import JSONResponse
from sqlalchemy import create_engine

from backend.app.identity.auth.dependencies import (
    require_authenticated_session,
    require_permission,
)
from backend.app.identity.auth.repository import (
    SQLAlchemyUserIdentityRepository,
    build_session_factory,
    identity_metadata,
)
from backend.app.identity.auth.service import IdentityAccessService, utc_now
from backend.app.shared.auth.errors import (
    AuthenticationError,
    AuthorizationError,
    InvalidIdentityError,
    MissingIdentityError,
)
from backend.app.shared.auth.extractors import HeaderClaimsExtractor
from backend.app.shared.auth.models import AuthenticatedSession
from backend.app.shared.auth.normalizer import IdentityNormalizer
from backend.app.shared.config.auth_config import AuthSettings
from backend.app.shared.rbac.service import RolePermissionResolver


def create_app(
    settings: AuthSettings | None = None,
    user_repository: SQLAlchemyUserIdentityRepository | None = None,
    clock: Callable[[], datetime] = utc_now,
) -> FastAPI:
    """Create the identity-access FastAPI application."""
    resolved_settings = settings or AuthSettings.from_env()

    if user_repository is None:
        database_url = resolved_settings.database_url
        _ensure_parent_path(database_url)
        engine = create_engine(database_url, future=True)
        identity_metadata.create_all(engine)
        user_repository = SQLAlchemyUserIdentityRepository(build_session_factory(engine))

    role_permission_resolver = RolePermissionResolver(
        group_role_map=resolved_settings.group_role_map,
        role_permissions=resolved_settings.role_permissions,
        role_priority=resolved_settings.role_priority,
    )
    claims_extractor = HeaderClaimsExtractor(resolved_settings)
    identity_normalizer = IdentityNormalizer(
        claim_mapping=resolved_settings.claim_mapping,
        role_permission_resolver=role_permission_resolver,
        group_delimiter=resolved_settings.group_delimiter,
    )
    service = IdentityAccessService(
        claims_extractor=claims_extractor,
        identity_normalizer=identity_normalizer,
        user_repository=user_repository,
        clock=clock,
    )

    app = FastAPI(title="REQ-002 Identity Access API", version="1.0.0")
    app.state.identity_access_service = service
    app.state.auth_settings = resolved_settings

    @app.exception_handler(AuthenticationError)
    async def handle_authentication_error(
        request: Request, exc: AuthenticationError
    ) -> JSONResponse:
        del request
        return JSONResponse(
            status_code=401,
            content={
                "error": {
                    "code": "authentication_failed",
                    "message": _authentication_message(exc),
                }
            },
        )

    @app.exception_handler(AuthorizationError)
    async def handle_authorization_error(
        request: Request, exc: AuthorizationError
    ) -> JSONResponse:
        del request
        return JSONResponse(
            status_code=403,
            content={
                "error": {
                    "code": "authorization_failed",
                    "message": str(exc) or "Permission denied.",
                }
            },
        )

    @app.middleware("http")
    async def authenticate_on_request(request: Request, call_next):  # type: ignore[no-untyped-def]
        if service.has_identity_material(request):
            try:
                request.state.authenticated_session = service.authenticate_request(request)
            except AuthenticationError as exc:
                request.state.authentication_error = exc

        return await call_next(request)

    @app.get("/health")
    def health() -> dict[str, str]:
        return {"status": "ok"}

    @app.get("/auth/me")
    def read_me(
        authenticated_session: AuthenticatedSession = Depends(require_authenticated_session),
    ) -> dict[str, object]:
        return _session_payload(authenticated_session)

    @app.get("/auth/protected/upload")
    def protected_upload(
        authenticated_session: AuthenticatedSession = Depends(require_permission("upload")),
    ) -> dict[str, object]:
        return _permission_payload("upload", authenticated_session)

    @app.get("/auth/protected/validate")
    def protected_validate(
        authenticated_session: AuthenticatedSession = Depends(require_permission("validate")),
    ) -> dict[str, object]:
        return _permission_payload("validate", authenticated_session)

    @app.get("/auth/protected/search")
    def protected_search(
        authenticated_session: AuthenticatedSession = Depends(require_permission("search")),
    ) -> dict[str, object]:
        return _permission_payload("search", authenticated_session)

    @app.get("/auth/protected/export")
    def protected_export(
        authenticated_session: AuthenticatedSession = Depends(require_permission("export")),
    ) -> dict[str, object]:
        return _permission_payload("export", authenticated_session)

    @app.get("/auth/protected/qa")
    def protected_qa(
        authenticated_session: AuthenticatedSession = Depends(require_permission("qa")),
    ) -> dict[str, object]:
        return _permission_payload("qa", authenticated_session)

    return app


def _authentication_message(exc: AuthenticationError) -> str:
    if isinstance(exc, MissingIdentityError):
        return "Authentication is required for this route."
    if isinstance(exc, InvalidIdentityError):
        return "Identity claims are invalid."
    return str(exc) or "Authentication failed."


def _permission_payload(
    permission: str, authenticated_session: AuthenticatedSession
) -> dict[str, object]:
    return {
        "ok": True,
        "permission": permission,
        "subject": authenticated_session.identity.subject,
        "roles": list(authenticated_session.identity.roles),
    }


def _session_payload(authenticated_session: AuthenticatedSession) -> dict[str, object]:
    identity = authenticated_session.identity
    user = authenticated_session.user
    return {
        "subject": identity.subject,
        "email": identity.email,
        "display_name": identity.display_name,
        "groups": list(identity.groups),
        "roles": list(identity.roles),
        "permissions": list(identity.permissions),
        "user": {
            "id": user.id,
            "external_subject": user.external_subject,
            "email": user.email,
            "display_name": user.display_name,
            "role": user.role,
            "is_active": user.is_active,
            "last_login_at": user.last_login_at.isoformat() if user.last_login_at else None,
        },
        "authenticated_at": authenticated_session.authenticated_at.isoformat(),
    }


def _ensure_parent_path(database_url: str) -> None:
    if not database_url.startswith("sqlite:///"):
        return
    database_path = database_url.removeprefix("sqlite:///")
    path = Path(database_path)
    if path.parent and not path.parent.exists():
        path.parent.mkdir(parents=True, exist_ok=True)
