            "search": ("search",),
            "export": ("export", "search"),
            "qa": ("qa", "search"),
            "admin": ("upload", "validate", "search", "export", "qa"),
        },
        role_priority=("admin", "validator", "operator", "export", "qa", "search", "viewer"),
    )


